// Cloudflare Worker entry: the OpenNext app for HTTP, plus the daily cron.
// The cron does one thing: call run_daily_maintenance() in Supabase (all the
// logic is in SQL, so it fits the free plan's CPU limit).

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

type Env = { NEXT_PUBLIC_SUPABASE_URL?: string; SUPABASE_SERVICE_ROLE_KEY?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

async function runDailyMaintenance(env: Env): Promise<void> {
  const url = env.NEXT_PUBLIC_SUPABASE_URL;
  const key = env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new Error("daily maintenance: Supabase configuration missing");
  const headers: Record<string, string> = { apikey: key, "content-type": "application/json" };
  // Legacy service_role keys are JWTs and also go in Authorization.
  if (key.startsWith("eyJ")) headers.authorization = `Bearer ${key}`;
  const res = await fetch(`${url}/rest/v1/rpc/run_daily_maintenance`, { method: "POST", headers, body: "{}" });
  if (!res.ok) throw new Error(`daily maintenance failed: HTTP ${res.status}`);
  console.log("daily maintenance:", await res.text());
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    ctx.waitUntil(runDailyMaintenance(env));
  },
};

